SELECT businessId AS id, businessName AS name, orderTypeId AS category_id, businessImg AS cover_url, 4.9 AS rating, 300 AS monthly_sales, deliveryPrice AS delivery_fee, starPrice AS start_price, 3.2 AS distance_km, 30 AS delivery_time_min, businessExplain AS announcement, 'ACTIVE' AS status FROM business
orderTypeId = #{categoryId}
AND businessName LIKE CONCAT('%', #{keyword}, '%')
